// ChangeServiceHandler is an implementation of the dockwell.v1.ChangeService service.
type ChangeServiceHandler interface {
	// ProposeChange plans a set of edits and records them as a planned
	// change, ready to apply or discard. Planning asks each server's agent
	// what the edits would take there, and changes nothing on any server. The
	// same edits against the same state give the same plan, and the same
	// fingerprint unless they edit a kind that may hold secrets, which each
	// change digests for itself.
	//
	// An edit that sets a secret's value is a rotation: it plans as a change,
	// and restarts what uses the secret, whatever the value is. So a plan
	// never says whether it is the value already there. Any other sensitive
	// field, such as a container's environment, compares as usual: an equal
	// value is no change, and a plan masks one that differs.
	ProposeChange(context.Context, *connect.Request[v1.ProposeChangeRequest]) (*connect.Response[v1.ProposeChangeResponse], error)
	// GetChange returns one change, with its plan and the progress of each of
	// its steps.
	GetChange(context.Context, *connect.Request[v1.GetChangeRequest]) (*connect.Response[v1.GetChangeResponse], error)
	// ListChanges returns changes, newest first, a page at a time. Each
	// change's plan is in brief: its fingerprint, summary, undo window and
	// whether it is destructive. GetChange has the plan in full.
	ListChanges(context.Context, *connect.Request[v1.ListChangesRequest]) (*connect.Response[v1.ListChangesResponse], error)
	// ApplyChange carries out a planned change. It plans again, and refuses
	// if any resource changed since, or if the servers no longer match the
	// plan; either way, propose the edits again and review the new plan.
	// Otherwise it commits the change's revisions and starts running its
	// steps, and returns the change as it starts applying. The steps run to
	// an end whether or not the caller waits. Follow them with WatchChange,
	// or by polling GetChange. If a step fails, Dockwell starts rolling back what
	// was done, in a change of its own, named in rolled_back_by. That runs on after
	// this change has failed, may wait for a server, and may fail too, so read
	// rollback_status for how it went.
	//
	// A plan that destroys data, may cut off access, or lets two containers
	// write to one place needs the fingerprint of the plan you reviewed, and a
	// signed-in session: no API token may apply one.
	ApplyChange(context.Context, *connect.Request[v1.ApplyChangeRequest]) (*connect.Response[v1.ApplyChangeResponse], error)
	// WatchChange streams a change: first the change as it stands, then each
	// step's progress as it moves on, and the change again whenever its state
	// does. It ends once the change is applied, failed or discarded, so a
	// planned change is watched until someone applies or discards it. Any
	// number of clients can watch one change, whoever applies it.
	WatchChange(context.Context, *connect.Request[v1.WatchChangeRequest], *connect.ServerStream[v1.WatchChangeResponse]) error
	// UndoChange plans putting back everything an applied change did, as a
	// new change; apply it to carry it out. It is refused once the change is
	// older than its undo window, or when a resource it touched has changed
	// again since: undo that later change first, or edit the resource.
	UndoChange(context.Context, *connect.Request[v1.UndoChangeRequest]) (*connect.Response[v1.UndoChangeResponse], error)
	// ConfirmChange keeps a change to a server's firewall that waits for its
	// confirmation (Change.confirmation), once you have checked that you can
	// still reach the server as the confirmation says. Only the person who
	// applied it may confirm it, in the session they applied it from. Without a
	// confirmation in time, the server puts back its firewall as it was, and the
	// change rolls back (ADR 0052). A server's firewall is the whole server's,
	// so confirming is an admin's, as applying such a change is, and no API
	// token can call it.
	ConfirmChange(context.Context, *connect.Request[v1.ConfirmChangeRequest]) (*connect.Response[v1.ConfirmChangeResponse], error)
	// DiscardChange drops a planned change without applying it. The change
	// stays on record as discarded.
	DiscardChange(context.Context, *connect.Request[v1.DiscardChangeRequest]) (*connect.Response[v1.DiscardChangeResponse], error)
	// RestartService plans restarting a service on every server it runs on: as
	// a deploy does, a new container takes over once it is healthy, where the
	// service can have two at once, and otherwise the old one stops first, and
	// the plan says for how long. It is a change, with a plan to apply or
	// discard. It makes no revision, as the spec stays as it is, so it has
	// nothing to undo, and a restart that fails leaves the revision where it was.
	RestartService(context.Context, *connect.Request[v1.RestartServiceRequest]) (*connect.Response[v1.RestartServiceResponse], error)
	// PlanInstallUpdates plans installing the package updates waiting on
	// servers: the security fixes, every update, or the packages named. Each
	// server's agent simulates the exact install, versions pinned, and the plan
	// lists every package it installs, those it pulls in too, whether a reboot
	// follows and whether Docker restarts. It's a change with a plan and no
	// revision, as a restart is: an upgrade can't be undone, and the plan says
	// so. Applying it takes a person's passkey, as it runs as root on the
	// server. See
	// docs/adr/0064-a-change-on-a-server-installing-updates-and-rebooting.md.
	PlanInstallUpdates(context.Context, *connect.Request[v1.PlanInstallUpdatesRequest]) (*connect.Response[v1.PlanInstallUpdatesResponse], error)
	// PlanReboot plans rebooting servers: an edit of each server's host that makes
	// no revision. The plan says that everything on each server goes offline
	// until it's back, and on the control server that the panel and the API stop
	// with it and come back on their own. Applying it takes a person's passkey,
	// as it acts as root on the server. A reboot's step passes once the server's
	// agent connects from another boot, and fails if none has after 15 minutes.
	// See docs/adr/0064-a-change-on-a-server-installing-updates-and-rebooting.md.
	PlanReboot(context.Context, *connect.Request[v1.PlanRebootRequest]) (*connect.Response[v1.PlanRebootResponse], error)
	// PlanAgentUpgrade plans upgrading servers' agents to the control plane's own
	// version, which must be a release (ADR 0094). Each server whose agent runs it
	// already takes no step, and the control server is never in it, as its agent is
	// the control plane. The plan carries the control plane's own install script,
	// by its SHA-256, which the agent checks before it runs it outside its own
	// service; the script checks the release with its pinned cosign, as an install
	// does. A step passes once the server's agent connects at the version asked,
	// and fails if it comes back at its old one or isn't back in 15 minutes.
	// Applying it takes a person's passkey, and it can't be undone.
	PlanAgentUpgrade(context.Context, *connect.Request[v1.PlanAgentUpgradeRequest]) (*connect.Response[v1.PlanAgentUpgradeResponse], error)
	// PlanRemoveServer plans taking a server out of the fleet: a change whose edits
	// move, stop or let go of what runs on it, as apps says, and which revokes the
	// server as its last act. The plan lists what moves, what stops, what stays on
	// the server, which certificates by DNS it re-issues and revokes, and what
	// becomes of its backups. With compromised, it revokes the server as it
	// commits, before any step, and takes none on it. It can't be undone, applying
	// it takes a person's passkey, and the control server can't be removed. See
	// docs/adr/0090-removing-a-server-and-marking-one-compromised.md.
	PlanRemoveServer(context.Context, *connect.Request[v1.PlanRemoveServerRequest]) (*connect.Response[v1.PlanRemoveServerResponse], error)
	// PlanSystemServiceAction plans an action on one of a server's system
	// services, its systemd units or OpenRC services: starting, stopping,
	// restarting or reloading it, or enabling, disabling, masking or unmasking it
	// at boot, on each server named. Each is an edit of the server's host that
	// makes no revision, as a reboot is: Dockwell keeps no desired state for a
	// unit, which the server's packages own, and undoing an action plans the one
	// that puts back how the unit stood. The plan says how the unit stands, what
	// stops or restarts with it and what starts it again. What Dockwell needs on
	// the server is guarded: its own units refuse every action, and Docker, SSH
	// and the network refuse a stop, a disable and a mask. A risky action, such as
	// restarting SSH or Docker, takes a person's passkey to apply. See
	// docs/adr/0082-acting-on-a-servers-system-services.md.
	PlanSystemServiceAction(context.Context, *connect.Request[v1.PlanSystemServiceActionRequest]) (*connect.Response[v1.PlanSystemServiceActionResponse], error)
	// PlanServerLabels plans setting and removing labels on servers, each as
	// key:value, such as region:eu: an edit of each server's host. Only the
	// control plane keeps labels, so the change takes no step on any server and
	// applies with them online or not, and its plan says so in a "labels_only"
	// note. A key is as a Kubernetes label's: a name of at most 63 characters,
	// letters, digits, -, _ and ., with an optional prefix, such as
	// example.com/tier. See docs/adr/0091-server-labels.md.
	PlanServerLabels(context.Context, *connect.Request[v1.PlanServerLabelsRequest]) (*connect.Response[v1.PlanServerLabelsResponse], error)
	// ListDrift compares what servers have with the latest revision of each
	// resource they should have, and returns every difference. It asks each
	// connected server's agent, and changes nothing.
	ListDrift(context.Context, *connect.Request[v1.ListDriftRequest]) (*connect.Response[v1.ListDriftResponse], error)
	// RevertDrift plans putting a drifted resource back to its latest
	// revision on the servers it runs on.
	RevertDrift(context.Context, *connect.Request[v1.RevertDriftRequest]) (*connect.Response[v1.RevertDriftResponse], error)
	// AdoptDrift plans keeping what a server has for a drifted resource: a
	// new revision that matches it. Nothing changes on that server; any other
	// server the resource runs on is brought to match, and the plan shows it.
	AdoptDrift(context.Context, *connect.Request[v1.AdoptDriftRequest]) (*connect.Response[v1.AdoptDriftResponse], error)
}

// NewChangeServiceHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
func NewChangeServiceHandler(svc ChangeServiceHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	changeServiceMethods := v1.File_dockwell_v1_change_proto.Services().ByName("ChangeService").Methods()
	changeServiceProposeChangeHandler := connect.NewUnaryHandler(
		ChangeServiceProposeChangeProcedure,
		svc.ProposeChange,
		connect.WithSchema(changeServiceMethods.ByName("ProposeChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceGetChangeHandler := connect.NewUnaryHandler(
		ChangeServiceGetChangeProcedure,
		svc.GetChange,
		connect.WithSchema(changeServiceMethods.ByName("GetChange")),
		connect.WithIdempotency(connect.IdempotencyNoSideEffects),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceListChangesHandler := connect.NewUnaryHandler(
		ChangeServiceListChangesProcedure,
		svc.ListChanges,
		connect.WithSchema(changeServiceMethods.ByName("ListChanges")),
		connect.WithIdempotency(connect.IdempotencyNoSideEffects),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceApplyChangeHandler := connect.NewUnaryHandler(
		ChangeServiceApplyChangeProcedure,
		svc.ApplyChange,
		connect.WithSchema(changeServiceMethods.ByName("ApplyChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceWatchChangeHandler := connect.NewServerStreamHandler(
		ChangeServiceWatchChangeProcedure,
		svc.WatchChange,
		connect.WithSchema(changeServiceMethods.ByName("WatchChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceUndoChangeHandler := connect.NewUnaryHandler(
		ChangeServiceUndoChangeProcedure,
		svc.UndoChange,
		connect.WithSchema(changeServiceMethods.ByName("UndoChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceConfirmChangeHandler := connect.NewUnaryHandler(
		ChangeServiceConfirmChangeProcedure,
		svc.ConfirmChange,
		connect.WithSchema(changeServiceMethods.ByName("ConfirmChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceDiscardChangeHandler := connect.NewUnaryHandler(
		ChangeServiceDiscardChangeProcedure,
		svc.DiscardChange,
		connect.WithSchema(changeServiceMethods.ByName("DiscardChange")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceRestartServiceHandler := connect.NewUnaryHandler(
		ChangeServiceRestartServiceProcedure,
		svc.RestartService,
		connect.WithSchema(changeServiceMethods.ByName("RestartService")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanInstallUpdatesHandler := connect.NewUnaryHandler(
		ChangeServicePlanInstallUpdatesProcedure,
		svc.PlanInstallUpdates,
		connect.WithSchema(changeServiceMethods.ByName("PlanInstallUpdates")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanRebootHandler := connect.NewUnaryHandler(
		ChangeServicePlanRebootProcedure,
		svc.PlanReboot,
		connect.WithSchema(changeServiceMethods.ByName("PlanReboot")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanAgentUpgradeHandler := connect.NewUnaryHandler(
		ChangeServicePlanAgentUpgradeProcedure,
		svc.PlanAgentUpgrade,
		connect.WithSchema(changeServiceMethods.ByName("PlanAgentUpgrade")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanRemoveServerHandler := connect.NewUnaryHandler(
		ChangeServicePlanRemoveServerProcedure,
		svc.PlanRemoveServer,
		connect.WithSchema(changeServiceMethods.ByName("PlanRemoveServer")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanSystemServiceActionHandler := connect.NewUnaryHandler(
		ChangeServicePlanSystemServiceActionProcedure,
		svc.PlanSystemServiceAction,
		connect.WithSchema(changeServiceMethods.ByName("PlanSystemServiceAction")),
		connect.WithHandlerOptions(opts...),
	)
	changeServicePlanServerLabelsHandler := connect.NewUnaryHandler(
		ChangeServicePlanServerLabelsProcedure,
		svc.PlanServerLabels,
		connect.WithSchema(changeServiceMethods.ByName("PlanServerLabels")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceListDriftHandler := connect.NewUnaryHandler(
		ChangeServiceListDriftProcedure,
		svc.ListDrift,
		connect.WithSchema(changeServiceMethods.ByName("ListDrift")),
		connect.WithIdempotency(connect.IdempotencyNoSideEffects),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceRevertDriftHandler := connect.NewUnaryHandler(
		ChangeServiceRevertDriftProcedure,
		svc.RevertDrift,
		connect.WithSchema(changeServiceMethods.ByName("RevertDrift")),
		connect.WithHandlerOptions(opts...),
	)
	changeServiceAdoptDriftHandler := connect.NewUnaryHandler(
		ChangeServiceAdoptDriftProcedure,
		svc.AdoptDrift,
		connect.WithSchema(changeServiceMethods.ByName("AdoptDrift")),
		connect.WithHandlerOptions(opts...),
	)
	return "/dockwell.v1.ChangeService/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case ChangeServiceProposeChangeProcedure:
			changeServiceProposeChangeHandler.ServeHTTP(w, r)
		case ChangeServiceGetChangeProcedure:
			changeServiceGetChangeHandler.ServeHTTP(w, r)
		case ChangeServiceListChangesProcedure:
			changeServiceListChangesHandler.ServeHTTP(w, r)
		case ChangeServiceApplyChangeProcedure:
			changeServiceApplyChangeHandler.ServeHTTP(w, r)
		case ChangeServiceWatchChangeProcedure:
			changeServiceWatchChangeHandler.ServeHTTP(w, r)
		case ChangeServiceUndoChangeProcedure:
			changeServiceUndoChangeHandler.ServeHTTP(w, r)
		case ChangeServiceConfirmChangeProcedure:
			changeServiceConfirmChangeHandler.ServeHTTP(w, r)
		case ChangeServiceDiscardChangeProcedure:
			changeServiceDiscardChangeHandler.ServeHTTP(w, r)
		case ChangeServiceRestartServiceProcedure:
			changeServiceRestartServiceHandler.ServeHTTP(w, r)
		case ChangeServicePlanInstallUpdatesProcedure:
			changeServicePlanInstallUpdatesHandler.ServeHTTP(w, r)
		case ChangeServicePlanRebootProcedure:
			changeServicePlanRebootHandler.ServeHTTP(w, r)
		case ChangeServicePlanAgentUpgradeProcedure:
			changeServicePlanAgentUpgradeHandler.ServeHTTP(w, r)
		case ChangeServicePlanRemoveServerProcedure:
			changeServicePlanRemoveServerHandler.ServeHTTP(w, r)
		case ChangeServicePlanSystemServiceActionProcedure:
			changeServicePlanSystemServiceActionHandler.ServeHTTP(w, r)
		case ChangeServicePlanServerLabelsProcedure:
			changeServicePlanServerLabelsHandler.ServeHTTP(w, r)
		case ChangeServiceListDriftProcedure:
			changeServiceListDriftHandler.ServeHTTP(w, r)
		case ChangeServiceRevertDriftProcedure:
			changeServiceRevertDriftHandler.ServeHTTP(w, r)
		case ChangeServiceAdoptDriftProcedure:
			changeServiceAdoptDriftHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

